== src/api/prices.js
     1	// Prices are stored in cents. The API returns them in pesos.
     2	export function unitPrice(item) {
     3	  return item.cents / 10;
     4	}
     5	
     6	export function lineTotal(item) {
     7	  return unitPrice(item) * item.qty;
     8	}
== src/web/cart.js
     1	import { lineTotal } from "../api/prices.js";
     2	
     3	export const LABEL = "Total";
     4	
     5	export function cartTotal(items) {
     6	  return items.reduce((sum, item) => sum + lineTotal(item), 0);
     7	}
     8	
     9	export function render(items) {
    10	  return `${LABEL}: $${cartTotal(items)}`;
    11	}
== test/cart.test.js
     1	import { test } from "node:test";
     2	import assert from "node:assert/strict";
     3	import { cartTotal, render, LABEL } from "../src/web/cart.js";
     4	
     5	const items = [{ cents: 150000, qty: 2 }, { cents: 99000, qty: 1 }];
     6	
     7	test("the cart total is in pesos", () => {
     8	  assert.equal(cartTotal(items), 3990);
     9	});
    10	
    11	test("the label says the currency", () => {
    12	  assert.equal(LABEL, "Total (CLP)");
    13	  assert.equal(render(items), "Total (CLP): $3990");
    14	});
